void Solver::rephase() {
    // Increment rephase counter
    rephases++;

    // Adjust threshold based on trail length trend
    if (trail.size() > threshold) {
        // If trail is growing, increase threshold more aggressively
        threshold = trail.size() * 1.1;
    } else {
        // If trail is shrinking, reduce threshold moderately
        threshold *= 0.85;
    }

    // Dynamically adjust rephase_limit based on solver performance
    if (conflicts > 0) {
        double conflict_rate = (double)conflicts / restarts;
        if (conflict_rate > 50.0) {
            // High conflict rate: increase rephase_limit more aggressively
            rephase_limit += 16384;
        } else if (conflict_rate < 10.0) {
            // Low conflict rate: increase rephase_limit conservatively
            rephase_limit += 4096;
        } else {
            // Moderate conflict rate: standard increase
            rephase_limit += 8192;
        }
    }

    // Apply phase diversification periodically
    if (rephases % 5 == 0) {
        // Every 5th rephase, diversify phases more aggressively
        for (int i = 1; i <= vars; i++) {
            if (rand() % 100 < 40) {  // 40% chance to flip phase
                saved[i] = -saved[i];
            }
        }
    } else {
        // Normal rephase: update saved phases based on recent assignments
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                // If variable has been assigned recently, save that phase
                saved[i] = value[i];
            }
        }
    }
}
